import { readFile, writeFile } from 'node:fs/promises'

const root = new URL('../supabase/', import.meta.url)
const parts = [
  'migrations/003_existing_schema_fixes.sql',
  'functions/002_rpc_functions.sql',
  'seed.sql',
]
const header = `-- MediBook: complete setup for an EXISTING schema.
-- Generated by: node scripts/build-supabase-setup.mjs
-- Copy this ENTIRE file into a new Supabase SQL Editor query and run it.
-- Does not recreate enums or tables. Existing rows are preserved.
-- On an error, changes in this transaction are rolled back; do not run fragments.
begin;
-- Serialize repeated runs of this setup script.
select pg_advisory_xact_lock(684321987);
`
const sections = await Promise.all(parts.map(async (path) =>
  `-- Source: ${path}\n${await readFile(new URL(path, root), 'utf8')}`,
))
const verification = await readFile(new URL('verify_setup.sql', root), 'utf8')
await writeFile(new URL('complete_setup.sql', root),
  `${header}\n${sections.join('\n\n')}\n\nnotify pgrst, 'reload schema';\ncommit;\n\n${verification}`,
)
console.log('Generated supabase/complete_setup.sql')

// Existing projects can update just mobile validation without re-running the seed.
const rpc = await readFile(new URL('functions/002_rpc_functions.sql', root), 'utf8')
const bookingFunction = rpc.slice(0, rpc.indexOf('create or replace function public.cancel_appointment'))
await writeFile(new URL('migrations/004_sri_lankan_mobile.sql', root),
  `-- Generated by node scripts/build-supabase-setup.mjs.\n-- Update booking mobile validation without changing rows or access grants.\nbegin;\n${bookingFunction}\nnotify pgrst, 'reload schema';\ncommit;\nselect position('Sri Lankan mobile' in pg_get_functiondef('public.book_appointment(uuid,text,text)'::regprocedure)) > 0 as sri_lankan_mobile_enabled;\n`,
)
console.log('Generated supabase/migrations/004_sri_lankan_mobile.sql')
